# curvature cavities, grooves and cracks also count as occlusion; take the min with the height-difference AO
cav = clamp(-@high_curv / 20, 0, 1)
@ao = min(@ao_disp, 1 - 0.55 * cav) * (1 - 0.4 * @crevice) * @mask + (1 - @mask)
@basecolor = @basecolor * lerp(0.7, 1.0, @ao)
lum = dot(@basecolor, set(0.3, 0.59, 0.11))
# worn convex edges are smoother, moss and crevices rougher
@roughness = clamp(0.88 - 0.3 * clamp(@high_curv / 30, 0, 1) - 0.1 * lum + 0.08 * @moss + 0.06 * @crevice, 0.4, 1)
@metallic = 0
